bridge=new GameBridge();string idleConversation=Json(await bridge.Accept(Input("idle-turn",6),default))["conversation_id"]!.GetValue<string>();await bridge.StartAsync(default);await Wait(()=>runs.ContainsKey("idle-turn"));
